// Served at /manifest.webmanifest. Lets bestRead be added to a phone's home screen
// and open full screen, like an app. Icons are generated by scripts/app-icon.mjs.
export default function manifest() {
	return {
		id: '/',
		name: 'bestRead',
		short_name: 'bestRead',
		description: 'a minimalist reading tracker. just your books.',
		start_url: '/',
		scope: '/',
		display: 'standalone',
		orientation: 'portrait',
		background_color: '#ffffff',
		theme_color: '#ffffff',
		categories: ['books', 'lifestyle', 'productivity'],
		icons: [
			{src: '/icons/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any'},
			{src: '/icons/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any'},
			{src: '/icons/maskable-192.png', sizes: '192x192', type: 'image/png', purpose: 'maskable'},
			{src: '/icons/maskable-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable'},
			{src: '/icons/icon.svg', sizes: 'any', type: 'image/svg+xml', purpose: 'any'},
		],
	};
}
